mapper.select:
SELECT id_pedidoprof as id_pedido, p.nombres, p.nit,num_cladoc,periodo as cadena1, (CASE WHEN tag='X' THEN 0 ELSE precio_total END) as precio_total, c.codigomayor as cadena2, c.nombremayorista as cadena3
FROM ventas.pedidosprof p INNER JOIN ventas.clientemayor c ON p.idmayor = c.id_clientemayor
WHERE id_pedidoprof = #{id}
